-- Source: GEM Global Seismic Hazard Model (OpenQuake Mosaic) (12 rows)
-- Generated by gen_mart_models.py

with source as (
    select * from {{ source('ripple_raw', 'INTL_GEM_HAZARD') }}
)

select
    MODEL_VERSION as model_version,
    try_to_number(COUNTRY) as country,
    FIPS as fips,
    try_to_double(LATITUDE) as latitude,
    try_to_double(LONGITUDE) as longitude,
    PGA_10PCT_50YR as pga_10pct_50yr,
    VS30 as vs30,
    HAZARD_MODEL_ID as hazard_model_id,
    DOI as doi
from source
